"use client";

import { keepFormOnSubmit } from "@/lib/use-keep-form";
import { useActionState } from "react";
import { CheckCircle2 } from "lucide-react";
import { submitLead } from "@/app/actions/leads";

type Field =
  | { name: string; label: string; type?: "text" | "email" | "tel" | "number"; required?: boolean; placeholder?: string; full?: boolean }
  | { name: string; label: string; type: "textarea"; required?: boolean; placeholder?: string; full?: boolean }
  | { name: string; label: string; type: "select"; options: string[]; required?: boolean; full?: boolean }
  | { name: string; label: string; type: "checkboxes"; options: string[]; full?: boolean };

export function LeadForm({ type, fields, submitLabel, successText }: { type: "B2B_QUOTE" | "ENGRAVING" | "CONTACT"; fields: Field[]; submitLabel: string; successText: string }) {
  const [state, action, pending] = useActionState(submitLead, undefined);
  if (state?.ok) {
    return (
      <div className="flex flex-col items-center gap-2 rounded-lg bg-success/10 p-8 text-center">
        <CheckCircle2 className="h-10 w-10 text-success" aria-hidden />
        <p className="font-display text-xl font-semibold">Thank you!</p>
        <p className="text-sm">{successText}</p>
      </div>
    );
  }
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="grid gap-4 sm:grid-cols-2">
      <input type="hidden" name="type" value={type} />
      {/* Honeypot: hidden from humans, bots fill it. */}
      <input type="text" name="website" tabIndex={-1} autoComplete="off" className="hidden" aria-hidden />
      {fields.map((f) => {
        const id = `lead-${f.name}`;
        const err = state?.fieldErrors?.[f.name]?.[0];
        return (
          <div key={f.name} className={f.full || f.type === "textarea" || f.type === "checkboxes" ? "sm:col-span-2" : ""}>
            <label className="label" htmlFor={id}>{f.label}{"required" in f && f.required && <span className="text-maroon"> *</span>}</label>
            {f.type === "textarea" ? (
              <textarea id={id} name={f.name} rows={4} className="input" required={f.required} placeholder={f.placeholder} maxLength={2000} />
            ) : f.type === "select" ? (
              <select id={id} name={f.name} className="input" required={f.required}>
                {f.options.map((o) => <option key={o}>{o}</option>)}
              </select>
            ) : f.type === "checkboxes" ? (
              <div className="grid gap-2 sm:grid-cols-2">
                {f.options.map((o) => (
                  <label key={o} className="flex items-center gap-2 text-sm"><input type="checkbox" name={f.name} value={o} className="accent-brass" />{o}</label>
                ))}
              </div>
            ) : (
              <input id={id} name={f.name} type={f.type ?? "text"} className="input" required={f.required} placeholder={f.placeholder} maxLength={200} />
            )}
            {err && <p className="mt-1 text-xs text-danger">{err}</p>}
          </div>
        );
      })}
      {state?.error && <p className="text-sm text-danger sm:col-span-2">{state.error}</p>}
      <button disabled={pending} className="btn-primary py-3 sm:col-span-2">{pending ? "Sending…" : submitLabel}</button>
    </form>
  );
}
